for a in ARTICLES:
    LINKS[a['board']] = a['h1']

PM = '<svg class="pm" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 5v14M5 12h14"></path></svg>'


def e(s):
    return html.escape(s, quote=False)


def money(n):
    return f'{n:,}'.replace(',', ' ') + ' ₸'


def block(b):
    kind = b[0]
    if kind == 'h2':
        return f'<h2>{e(b[1][0])}</h2>'
    if kind == 'p':
        return f'<p>{e(b[1][0])}</p>'
    if kind == 'ul':
        return '<ul>' + ''.join(f'<li>{e(x[0])}</li>' for x in b[1]) + '</ul>'
    if kind == 'table':
        head = ''.join(f'<th>{e(h[0])}</th>' for h in b[1])
        rows = ''
        for r in b[2]:
            rows += '<tr>' + ''.join(f'<td{" class=\"num\"" if "₸" in c[0] and i == len(r) - 1 else ""}>{e(c[0])}</td>' for i, c in enumerate(r)) + '</tr>'
        return f'<div class="tw"><table class="tbl"><thead><tr>{head}</tr></thead><tbody>{rows}</tbody></table></div>'
    if kind == 'videos':
        out = ''
        for f, cap, wide in b[1]:
            out += (f'<figure class="vfig{" wide" if wide else ""}"><video controls playsinline muted preload="none" poster="/media/{f}.jpg" '
                    f'src="/media/{f}.mp4"></video><figcaption>{e(cap[0])}</figcaption></figure>')
        return f'<div class="vgrid">{out}</div>'
    if kind == 'more':
        links = ', '.join(f'<a href="{t}">{e(LINKS[t][0])}</a>' for t in b[2])
        return f'<p>{e(b[1][0])} {links}.</p>'
    raise ValueError(kind)


def board(a, head, foot):
    h, _, alt = IMG[a['img']]
    src = f'/_blob/{h}'
    if a.get('hero'):
        src, alt = a['hero'][0], a['hero'][1][0]
    head = head.replace('</style>', VCSS + '</style>', 1)
    body = '\n'.join(block(b) for b in a['body'])
    faq = '\n'.join(f'<details><summary>{e(q[0])}{PM}</summary><p class="ans">{e(x[0])}</p></details>' for q, x in a['faq'])
    rel = '\n'.join(f'<a href="{t}">{e(LINKS[t][0])}</a>' for t in a['rel'])
    name, price, book = a['card']
    head = re.sub(r'<title>.*?</title>', f'<title>{e(a["title"][0])}</title>', head, flags=re.S)
    return f'''{head}<section style="padding: 40px 0 0">
<div class="w" style="display: flex; flex-direction: column; gap: 28px">
<nav aria-label="Хлебные крошки" style="display: flex; gap: 10px; font-size: 14px; color: #6F7B8B"><a href="Main.dc.html" style="color: #8A96A6">Главная</a><span>/</span><a href="Blog.dc.html" style="color: #8A96A6">Полезное</a><span>/</span><span style="color: #C9D1DB">{e(a["crumb"][0])}</span></nav>
<h1 class="hd" style="font-size: 60px; line-height: 1.04; font-weight: 800; max-width: 980px">{e(a["h1"][0])}</h1>
<div style="display: flex; align-items: center; gap: 14px"><span style="width: 44px; height: 44px; border-radius: 50%; background: #1B2638; color: #C9D1DB; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 15px">ВН</span><div style="display: flex; flex-direction: column; gap: 2px"><span style="font-size: 15px; font-weight: 600">Виктор Новиков</span><span style="font-size: 13px; color: #8A96A6">{e(byline(a)[0])}</span></div></div>
<div style="height: 520px; border-radius: 20px; overflow: hidden; background: #11161E; margin-top: 8px"><img class="cover" src="{src}" alt="{e(alt)}"></div>
</div>
</section>

<section style="padding: 64px 0 120px">
<div class="w lay">
<article class="art">
<div style="padding: 28px 30px; border-radius: 16px; background: #11161E; border: 1px solid rgba(255,255,255,.08); display: flex; flex-direction: column; gap: 10px">
<div class="hd" style="font-size: 20px; font-weight: 700; color: #FFFFFF">Коротко</div>
<p style="font-size: 17px">{e(a["short"][0])}</p>
</div>

{body}

<h2>Частые вопросы</h2>
<div>
{faq}
</div>

<div style="margin-top: 36px; padding: 32px; border-radius: 18px; background: #0E131A; border: 1px solid rgba(255,255,255,.1); display: flex; flex-direction: column; gap: 14px">
<h2 style="margin-top: 0; font-size: 28px">{e(a["cta"][0][0])}</h2>
<p>{e(CTA_HEAD[0] + a["cta"][1][0] + CTA_TAIL[0])}<a href="{WA}">+7 747 495 61 65</a>.</p>
</div>
</article>

<aside style="position: sticky; top: 24px; display: flex; flex-direction: column; gap: 22px">
<div style="padding: 28px; border-radius: 18px; background: #11161E; border: 1px solid rgba(255,255,255,.08); display: flex; flex-direction: column; gap: 16px">
<a class="hd" href="{book}" style="font-size: 22px; font-weight: 700; color: #FFFFFF">{e(name[0])}</a>
<div class="num" style="font-size: 28px; font-weight: 600"><span style="font-size: 15px; color: #8A96A6">от </span>{money(price)}</div>
<a class="btn btn-p" href="{WA}">Записаться</a>
<p style="font-size: 13px; color: #8A96A6">Алматы, Аносова 91 · 09:30–19:00</p>
</div>
<div style="display: flex; flex-direction: column; gap: 12px; font-size: 15px">
<div style="color: #8A96A6">Ещё по теме</div>
{rel}
</div>
</aside>
</div>
</section>

{foot}'''


VCSS = '''.vgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.vfig{margin:0;display:flex;flex-direction:column;gap:8px}.vfig.wide{grid-column:1/-1}
.vfig video{width:100%;border-radius:14px;background:#11161E;display:block}
.vfig figcaption{font-size:14px;color:#8A96A6}
'''


def byline(a):
    d = a.get('date', DATE)
    return (f'основатель VibroTest · {d[0]} · {a["min"]} минут', f'VibroTest негізін қалаушы · {d[1]} · {a["min"]} минут')


def main():
    t = (ROOT / 'src' / 'art-steering-knock.dc.html').read_text(encoding='utf-8')
    head = t[:t.index('<section style="padding: 40px 0 0">')]
    foot = t[t.index('<footer'):]
    have = json.loads((ROOT / 'i18n' / 'kk.json').read_text(encoding='utf-8'))
    have.update(json.loads((ROOT / 'i18n' / 'kk-v2.json').read_text(encoding='utf-8')))
    kk = {}

    def add(pair):
        ru, k = pair
        if k:
            kk[ru] = k
        elif ru not in have and ru not in kk:
            raise SystemExit(f'no KK for: {ru}')

    for a in ARTICLES:
        for f in ('title', 'h1', 'crumb', 'short', 'cat'):
            add(a[f])
        add(byline(a))
        add(a['hero'][1] if a.get('hero') else (IMG[a['img']][2], None))
        for b in a['body']:
            if b[0] in ('h2', 'p'):
                add(b[1])
            elif b[0] == 'ul':
                for x in b[1]:
                    add(x)
            elif b[0] == 'table':
                for c in b[1] + [c for r in b[2] for c in r]:
                    if re.search('[А-Яа-яЁё]', c[0]):
                        add(c)
            elif b[0] == 'more':
                add(b[1])
            elif b[0] == 'videos':
                for _, cap, _w in b[1]:
                    add(cap)
        for q, x in a['faq']:
            add(q)
            add(x)
        add(a['cta'][0])
        add(((CTA_HEAD[0] + a['cta'][1][0] + CTA_TAIL[0]).strip(), (CTA_HEAD[1] + a['cta'][1][1] + CTA_TAIL[1]).strip()))
        add(a['card'][0])
        (ROOT / 'src' / a['board']).write_text(board(a, head, foot), encoding='utf-8')
    for ru, k in LINKS.values():
        add((ru, k))
    (ROOT / 'i18n' / 'kk-v2-art.json').write_text(json.dumps(kk, ensure_ascii=False, indent=1) + '\n', encoding='utf-8')
    meta = [{'board': a['board'], 'slug': a['slug'], 'date': a.get('iso', ISO_DATE), 'img': IMG[a['img']][1], 'alt': IMG[a['img']][2],
             'h1': a['h1'], 'cat': a['cat'], 'min': a['min'], 'svc': [t for b in a['body'] if b[0] == 'more' for t in b[2]],
             **({'src': a['hero'][0], 'alt2': a['hero'][1]} if a.get('hero') else {})} for a in ARTICLES]
    (ROOT / 'i18n' / 'v2-articles.json').write_text(json.dumps(meta, ensure_ascii=False, indent=1) + '\n', encoding='utf-8')
    print(f'{len(ARTICLES)} articles, {len(kk)} KK strings')


if __name__ == '__main__':
    main()
